# Brand logos move from file storage into the database, so every server
# can show them without a shared disk or bucket.

import mimetypes

from django.core.files.storage import default_storage
from django.db import migrations, models


def copy_logo_files_into_database(apps, schema_editor):
    """Reads each saved logo file (where this migration runs, e.g. the
    laptop that holds media/) into its Brand row. A missing file is left
    as is; uploading the logo again on the Brand page fixes it."""
    Brand = apps.get_model("core", "Brand")
    for brand in Brand.objects.exclude(logo="").exclude(logo__isnull=True).filter(logo_data__isnull=True):
        try:
            with default_storage.open(brand.logo.name, "rb") as saved:
                data = saved.read()
        except (FileNotFoundError, OSError):
            continue
        Brand.objects.filter(pk=brand.pk).update(
            logo_data=data,
            logo_content_type=mimetypes.guess_type(brand.logo.name)[0] or "application/octet-stream",
        )


